-- ═══════════════════════════════════════════════════════════════
--  시연용 도매처 7곳 + 상품 카탈로그 305건 + 상품 이미지 760장
--
--  최종 평가(11/27~28) 라이브 시연에서 소매 마켓이 상품 6건으로는 비어 보인다.
--  V900 의 도매처 3곳(101~103)에 20건씩, 새 도매처 104~110 에 35건씩 얹는다. 전부 ON_SALE 이다.
--
--  이미지는 S3 버킷 ondo-dev-listing-images 의 listings/<게시글 id>/<n>.jpg 다.
--  색상옵션마다 한 장, sort_order 0 이 대표 이미지다.
--  기존 V900 의 가짜 주소(cdn.ondo.test)도 같은 버킷 주소로 바꾼다.
--
--  id 는 V900 다음 자리부터 쓴다 — 상품 1101~ · 게시글 2101~ · 옵션 3100~ · 색상옵션 4100~ · 이미지 5100~
--  ⚠️ 개발 환경 전용(db/seed). 운영에는 안 들어간다.
-- ═══════════════════════════════════════════════════════════════

